class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private int height(TreeNode node) {
    if (node == null) {
      return 0;
    }
    int left = height(node.left);
    if (left == -1) {
      return -1;
    }
    int right = height(node.right);
    if (right == -1) {
      return -1;
    }
    if (left - right > 1 || right - left > 1) {
      return -1;
    }
    return Math.max(left, right) + 1;
  }

  public boolean isBalanced(TreeNode root) {
    return height(root) != -1;
  }
}

class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:
        def height(node):
            if node is None:
                return 0
            left = height(node.left)
            if left == -1:
                return -1
            right = height(node.right)
            if right == -1:
                return -1
            if abs(left - right) > 1:
                return -1
            return max(left, right) + 1

        return height(root) != -1

impl Solution {
  fn height(node: &Option<Box<TreeNode>>) -> i32 {
    match node {
      None => 0,
      Some(n) => {
        let left = Solution::height(&n.left);
        if left == -1 {
          return -1;
        }
        let right = Solution::height(&n.right);
        if right == -1 {
          return -1;
        }
        if (left - right).abs() > 1 {
          return -1;
        }
        std::cmp::max(left, right) + 1
      }
    }
  }

  pub fn is_balanced(root: Option<Box<TreeNode>>) -> bool {
    Solution::height(&root) != -1
  }
}

const height = (node: TreeNode | null): number => {
  if (!node) return 0;
  const left = height(node.left);
  if (left === -1) return -1;
  const right = height(node.right);
  if (right === -1) return -1;
  if (Math.abs(left - right) > 1) return -1;
  return Math.max(left, right) + 1;
};

const isBalanced = (root: TreeNode | null): boolean => height(root) !== -1;
